{
    ReconcileModel {
        kind: K::kind(),
        init: || R::reconcile_init_state().marshal(),
        transition: |obj, resp_o, s| {
            let obj_um = K::unmarshal(obj)->Ok_0;
            let resp_o_um = match resp_o {
